using System;
using System.Linq;
using System.Collections.Generic;
using System.Globalization;
using System.Text.RegularExpressions;
namespace PeerChatDesktop {
public sealed class LogsDiagnosticInput {
    public string Scope="",Profile="",Log="",Status="",Unavailable="";public bool RetentionAvailable;public FailureSnapshot[] Failures=new FailureSnapshot[0];
}
public static class DiagnosticMetadataSafety {
    // Diagnostic metadata only: arbitrary frozen subsystem bodies are not imported/exported.
    static readonly Regex Content=new Regex(@"(?im)^.*\b(?:message|file|attachment)[_ -]?(?:contents?|body|text)\s*[=:].*$",RegexOptions.Compiled);
    public static string Clean(string text){return ConnectionsSafeText.Clean(Content.Replace(text??"","[redacted content]"));}
}
public sealed class LogsDiagnosticSnapshot {
    public string Scope,Profile,Banner,Status,Unavailable;public bool RetentionAvailable;
    public DiagnosticObservedEntry[] Logs=new DiagnosticObservedEntry[0],Failures=new DiagnosticObservedEntry[0],Interruptions=new DiagnosticObservedEntry[0];
}
public static class LogsDiagnosticProjection {
    static string Safe(string value){return DiagnosticMetadataSafety.Clean(value);}
    static DateTime? Time(string value){DateTime utc;return DateTime.TryParse(value,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out utc)?(DateTime?)(utc.Kind==DateTimeKind.Utc?utc:utc.ToUniversalTime()):null;}
    static DiagnosticObservedEntry Failure(FailureSnapshot f){var at=Time(f.TimestampUtc);bool interrupted=f.FailureDomain=="process_exit";return new DiagnosticObservedEntry{Id=Safe(f.Id),Utc=at,Severity=interrupted?"Warning":"Error",Subsystem=Safe(f.OperationType),Description=Safe(f.Title+" · "+f.Reason),Details=Safe("Profile-retained record — not asserted to belong to the current account/session\nRecorded UTC: "+(at.HasValue?ConnectionPreviewDisplay.Utc(at.Value):"Not retained")+(interrupted?" (last operation-marker update; actual termination time not retained)":"")+"\nFailure ID: "+f.Id+"\nOperation: "+f.OperationType+"\nOperation ID: "+f.OperationId+"\nGeneration: "+f.Generation+"\nDomain: "+f.FailureDomain+"\nStage: "+f.Stage+"\nReason: "+f.Reason+"\nModule: "+f.Module+"\nRecorded build: "+(f.Diagnostics==null?"Not retained":f.Diagnostics.Build)+"\nRecorded profile: "+(f.Diagnostics==null?"Not retained":f.Diagnostics.Profile)+"\nRecovery outcome: Not retained — no correlated recovery record\n"+(interrupted?"Evidence: retained unfinished-operation marker; NOT a confirmed crash, exception diagnosis or dump.\nException / stack / dump / termination time: Not retained":"Exception/stack/dump: Not retained as structured fields")+"\nFrozen diagnostic section names: "+(f.Diagnostics==null?"Not retained":String.Join(", ",(f.Diagnostics.Sections??new List<DiagnosticsSection>()).Take(16).Select(s=>s.Name)))+"\nArbitrary frozen subsystem bodies are not exported here; the original Connection & Diagnostics remains available.")};}
    public static LogsDiagnosticSnapshot Read(LogsDiagnosticInput input){
        input=input??new LogsDiagnosticInput{Unavailable="Diagnostic input unavailable"};var failures=(input.Failures??new FailureSnapshot[0]).Where(f=>f!=null).Take(15).Select(Failure).OrderByDescending(f=>f.Utc).ToArray();
        var events=ExistingConnectionsProvider.ReadEvents(Safe(input.Log),true).Select(e=>new DiagnosticObservedEntry{Id=e.UtcTimestamp+"/"+e.CorrelationId+"/"+e.Description,Utc=e.TimestampUtc,Severity=e.Severity.ToString(),Subsystem=e.Description.StartsWith("voice",StringComparison.OrdinalIgnoreCase)?"Voice":"Connections",Description=Safe(e.Description),Details=Safe(e.DetailsUtc+"\nSeverity is classified from existing recorded stage, not a newly measured error severity.")}).Take(300).ToArray();
        return new LogsDiagnosticSnapshot{Scope=Safe(input.Scope),Profile=Safe(input.Profile),Banner="REAL APPLICATION DIAGNOSTICS · profile-retained metadata ≠ current login/session · interrupted operation ≠ confirmed crash",Status=Safe(input.Status),Unavailable=Safe(input.Unavailable),RetentionAvailable=input.RetentionAvailable,Logs=events,Failures=failures,Interruptions=(input.Failures??new FailureSnapshot[0]).Where(f=>f!=null&&f.FailureDomain=="process_exit").Take(15).Select(Failure).OrderByDescending(f=>f.Utc).ToArray()};
    }
    public static DiagnosticObservedEntry[] Filter(IEnumerable<DiagnosticObservedEntry> source,string search,string severity,string subsystem){return (source??new DiagnosticObservedEntry[0]).Where(e=>(String.IsNullOrEmpty(severity)||severity=="All"||e.Severity==severity)&&(String.IsNullOrEmpty(subsystem)||subsystem=="All"||e.Subsystem==subsystem)&&(String.IsNullOrEmpty(search)||(e.Description+"\n"+e.Details).IndexOf(search,StringComparison.OrdinalIgnoreCase)>=0)).OrderBy(e=>e.Utc).ToArray();}
    public static DiagnosticUiSnapshot Overview(LogsDiagnosticSnapshot p){return new DiagnosticUiSnapshot{Sample=false,Context=new DiagnosticContext(DiagnosticSection.LogsCrashReports,p.Scope),Banner=p.Banner,Pages=new[]{new DiagnosticPage{Tab="Overview",Panels=new[]{HistoryDiagnosticProjection.Card("Application diagnostic sources","Profile",p.Profile,"Current application status",p.Status,"Profile connection metadata log",p.Logs.Length+" retained metadata events (max 300)","Retained failures",p.RetentionAvailable?p.Failures.Length+" profile-retained entries (max 15); empty can also mean unavailable/corrupt under the existing reader":"Unavailable — retention getter unavailable","Process-wide UI timing log","Not safely profile-attributed; not imported or exported","Current native diagnostics","Already integrated in the other five sections; no extra native polling here"),HistoryDiagnosticProjection.Card("Last known retained failure","Summary",p.Failures.Length>0?p.Failures[0].Summary:"Not retained / unavailable","Details",p.Failures.Length>0?p.Failures[0].Details:"No retained failure returned by the existing bounded reader","Current health limitation","An empty list does not prove error-free operation or complete crash detection."),HistoryDiagnosticProjection.Card("Crash and interruption availability","Interrupted operations",p.Interruptions.Length+" unfinished-operation markers; not confirmed crashes","Crash exception/stack/dump collection","Not instrumented as a crash-capture engine","Exact termination time","Not retained","Source failure",String.IsNullOrEmpty(p.Unavailable)?"No provider exception; underlying store completeness is not instrumented":p.Unavailable)}}}};}
    public static string Export(LogsDiagnosticSnapshot p,string scope){var text="PeerChat Logs / Crash Reports diagnostics\nBuild: "+PeerChat.VersionInfo.Display+"\nCaptured UTC: "+DateTime.UtcNow.ToString("o")+"\nProfile context: "+p.Scope+"\n"+p.Banner+"\nExport selection: "+scope+"\nLive status (not a historical event): "+p.Status+"\n";if(scope=="All metadata"||scope=="Application logs")text+="\nProfile-retained application metadata:\n"+String.Join("\n\n",p.Logs.Select(e=>e.Details));if(scope=="All metadata"||scope=="Retained failures")text+="\nProfile-retained failures:\n"+String.Join("\n\n",p.Failures.Select(e=>e.Details));if(scope=="All metadata"||scope=="Interrupted operations")text+="\nInterrupted-operation evidence — not confirmed crash reports:\n"+(p.Interruptions.Length==0?"Not retained":String.Join("\n\n",p.Interruptions.Select(e=>e.Details)));return Safe(text+"\nNo arbitrary frozen subsystem bodies, global UI logs, messages, file contents, credentials or dump files are exported. Crash capture completeness is not instrumented.");}
}
}
